INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Root Double: Before Crime * After Days - Xtend Edition', 'Rescue squad captain Watase Kasasagi wakes up without his memories in the middle of his most critical mission yet-- a nuclear meltdown at a research facility. In an unfamiliar place and without his years of training, he must rescue the survivors and escape... but could the key to the mystery behind the incident lie in the mind of Natsuhiko Tenkawa, a seemingly ordinary student?' FROM games WHERE igdb_id = 33617 ON CONFLICT (game_id, language_code) DO NOTHING;
