INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Westbound: Perils Ranch', 'Explore the lush woods and western mud bay in this Cowboys ranch town. Challenge yourself and build your own Cowboys township, city or village by clearing out a blissful obstacles and debris. Venture into this western island and create your own vivid bay. Have fun in this western farm simulation game.' FROM games WHERE igdb_id = 323325 ON CONFLICT (game_id, language_code) DO NOTHING;
