INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Push-Cars 2: On Europe Streets', '"Push-Cars 2: On Europe Streets" is a brand new game in the hugely successful “Push-Cars” series. This new challenge features brand new cars and cities and sees Sparky travels to Europe to enjoy new levels of this logic puzzle gameplay with new friends and foes. The good and eco friendly cars must leave the cities while the bad and polluting ones must crash and stay on the streets. The puzzle game to put the neurones of all the family to work, is back and better than ever!' FROM games WHERE igdb_id = 350462 ON CONFLICT (game_id, language_code) DO NOTHING;
