INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dominique-pamplemousse', 134677, '2013-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co868a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar17hp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dominique Pamplemousse', 'In this unique and offbeat stop motion musical detective adventure game, Dominique Pamplemousse, the titular protagonist, is a down-on-their-luck private investigator of ambiguous gender only one rent payment away from homelessness. When the CEO of a major record company shows up asking Dominique to locate a missing pop star, taking the job appears to be the straightforward thing to do. However, as things are never quite as they seem in these kinds of stories, Dominique winds up framed for a crime they didn''t commit, bringing to surface their mysterious past and the events that led them to take up shady detective work in the first place.
