INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Sword and Fairy 5 Prequel', 'The Legend of Sword and Fairy 5 Prequel is an action role-playing game developed by Softstar Technology (Beijing) Co., Ltd. It is the seventh installment in the Legend of Sword and Fairy (or Chinese Paladin) video game series and is the prequel of The Legend of Sword and Fairy 5. Set in a fictional version of ancient China, the game is based on the wuxia genre with elements of fantasy.' FROM games WHERE igdb_id = 78467 ON CONFLICT (game_id, language_code) DO NOTHING;
