INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Divo', 'Divo - This is an unusual, bright and dynamic arcade game, where you control a hamster in a cyber wheel! Our hero must, within a limited time, reach the finishing point of the level while simultaneously avoiding collisions with enemies and collecting all sorts of bonuses, to successfully complete each level! The game also has various elements of puzzles, where you have to find certain items in order to pass a certain obstacle. Levels are designed as a large tower (tower rotation depends on the movement of the main character) around which are placed all the game elements: platforms, teleporters, traps, etc.' FROM games WHERE igdb_id = 16482 ON CONFLICT (game_id, language_code) DO NOTHING;
