INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Detective Case and Clown Bot in: Murder in the Hotel Lisbon', 'Murder in the Hotel Lisbon is a videogame inspired by the classic point and click adventures from the 80’s and 90’s. It works through a simple interface of pointing and clicking. Everything that is essential for game progression can be clicked like characters, objects or doors. All the items collected are kept to be used later and are accessible at any time. The game can be saved at any time.' FROM games WHERE igdb_id = 3373 ON CONFLICT (game_id, language_code) DO NOTHING;
