INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avant-Garde Discerning Paralleler', 'Avant-Garde Discerning Paralleler has a total of 16 selectable stages and 2 difficulty levels. There are 2 player teams to choose from: Ran Yakumo with Chen, and Seiga Kaku with Kyouko Kasodani. Each team has a different play style and a different set of stages to play.
