INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penny Arcade''s On the Rain-Slick Precipice of Darkness 4', 'Penny Arcade’s “On the Rain-Slick Precipice of Darkness 4” concludes the saga of Tycho Brahe, Scion of The Long Project, and his almost certainly human partner Jonathan Gabriel. The world has been destroyed, but existence extends beyond this mortal plane in the gruesome Underhell! The new game expands considerably on its predecessor in size, scope and gameplay. Create the ultimate fighting force by recruiting bizarre, occasionally disgusting monsters and teaming them up with the best trainer for the job.' FROM games WHERE igdb_id = 14981 ON CONFLICT (game_id, language_code) DO NOTHING;
