INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Effect', 'Dead Effect is a sci-fi first-person shooter set aboard the starship ESS Meridian, which is bound for humanity''s first colonization attempt on Tau Ceti f. Players assume the role of a Unit 13 operative who awakens from cryosleep to find the vessel overrun with hostile, zombie-like crew members. The game combines traditional FPS gameplay with survival horror elements as players navigate through the abandoned spacecraft, uncovering the mystery behind the crew''s transformation while fighting for survival.' FROM games WHERE igdb_id = 17159 ON CONFLICT (game_id, language_code) DO NOTHING;
