INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Friends', 'Welcome to beautiful Heartlake City where summer fun awaits. Meet your new LEGO Friends and join them on exciting adventures that build friendships with the girls and allow you to express your individual style and personality as you explore the city. Shop for the latest outfits and accessories, select the perfect hairstyle, decorate your bedroom and even pick out a pet. Choose how to spend your summer vacation; whether you''d rather attend horse riding camp, perfect a dance routine, or care for an animal at the rescue center, you can do these things and more as you express your creativity, and build fun memories with your five new friends.' FROM games WHERE igdb_id = 6838 ON CONFLICT (game_id, language_code) DO NOTHING;
