INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bibi-blocksberg-das-grosse-hexenbesen-rennen-2', 222645, '2013-10-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7n0x.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bibi Blocksberg: Das große Hexenbesen-Rennen 2', 'The new Big Broom Race is characterized by completely revised and significantly improved graphics, which clearly surpass its predecessor and thus ensures even more identification with Bibi''s adventures. This time, the players are drawn to three worlds that fans of the little witch have already learned to love in the animated series: to Transylvania, to the Orient and to the dinosaurs. There is something for every taste here. Each of the 12 racetracks is characterized by special features that affect gameplay. From simple shortcuts, jumps and obstacles to spontaneous route changes during the race, everything is included. The airfield has increased to eight characters and also comes up with eight witches'' brooms that can be freely combined with each other. There are also eight completely renewed hex potions that provide excitement and invite you to play tactical games.' FROM games WHERE igdb_id = 222645 ON CONFLICT (game_id, language_code) DO NOTHING;
