INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty: Ghosts - Prestige Edition', 'Call of Duty: Ghosts takes place following a catastrophic event that changed the global balance of powers in the world. As a result, the United States is no longer recognized as a superpower. Ten years after the event, an unseen enemy emerges as a threat, but the remnants of US special forces from every branch came together to create an elite group of soldiers known as the "Ghosts", who are determined to eradicate all threats to protect the weak and the remains of America.' FROM games WHERE igdb_id = 102078 ON CONFLICT (game_id, language_code) DO NOTHING;
