INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-mansao', 342221, '2013-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9wv3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwn7u.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Mansão', 'A Mansão is a psychological survival horror game made by Will in RPG Maker XP, inspired by Silent Hill and the developer''s own nightmares. You play as an unnamed protagonist invited to a suspicious party at a nearby mansion. From the start, unsettling events—shadowy figures, eerie noises, and sudden deaths—hint at something sinister. Trapped inside, you must explore, evade danger, and uncover the terrifying truth without combat, relying on tension and atmosphere to deliver a chilling experience.' FROM games WHERE igdb_id = 342221 ON CONFLICT (game_id, language_code) DO NOTHING;
