INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Croods: Prehistoric Party!', 'The Croods: Prehistoric Party! features the lovable Croods family: Grug, Ugga, Eep, Thunk, Sandy, Gran and Guy, on a hilarious adventure through 30 unique and addictive party-style mini-games. Explore spectacular landscapes in an incredible new world filled with never-before-seen creatures as you battle your friends and family in this awesome adventure with up to four friends in multiplayer gameplay.' FROM games WHERE igdb_id = 25161 ON CONFLICT (game_id, language_code) DO NOTHING;
