INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Napoleon''s Campaigns', 'The greatest historical strategy game about Napoleon''s Campaigns is here! Napoleon''s Campaigns is a realistic simulation of the campaigns fought by the renowned French emperor between 1805 and 1815. In addition to reliving these landmarks of operational maneuver across Europe, the game also includes the Peninsula War (1808-1814) and even a what-if scenario where Napoleon invades England (1805).' FROM games WHERE igdb_id = 21362 ON CONFLICT (game_id, language_code) DO NOTHING;
