INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Zomboid', 'Project Zomboid is the ultimate in zombie survival. Alone or in MP: you loot, build, craft, fight, farm and fish in a struggle to survive. A hardcore RPG skillset, a vast map, a massively customisable sandbox and a cute tutorial raccoon await the unwary. So how will you die?' FROM games WHERE igdb_id = 3189 ON CONFLICT (game_id, language_code) DO NOTHING;
