INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wordly', 'Spell the longest words possible, claim your opponent''s tiles, and dominate the board in this exciting letter landgrab game. You can play against friends and family everywhere, on both smartphone and tablet, and challenge historical and literary greats -- such as Shakespeare, Cleopatra, and Count Dracula -- in "Play the Greats" mode, Wordly''s awesome single-player experience.' FROM games WHERE igdb_id = 323327 ON CONFLICT (game_id, language_code) DO NOTHING;
