INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StarCraft II: Heart of the Swarm', 'You are Sarah Kerrigan, former Queen of Blades. Once the most feared entity in the galaxy, you now wait in a cell in the depths of a high-security research laboratory. Before the murderous forces of the Terran Dominion close in, you must plot your escape to the dark reaches of space… and reclaim your living empire at the Heart of the Swarm.' FROM games WHERE igdb_id = 457 ON CONFLICT (game_id, language_code) DO NOTHING;
