INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Folk Tale', 'Folk Tale is a single-player fantasy village builder RPG game in which you lead a ragtag band of peasants in growing a small settlement into a thriving market town, while dastardly minions plot your downfall. Sound the rallying call and head out into the wilds with parties of heroes and fight back the tide of evil in a game of endless possibilities.
