INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 2013', 'The game features all eleven teams and twenty-two drivers competing in the 2013 season, as well as the nineteen circuits and Grands Prix. A "Classic Edition" of the game features additional drivers, cars and circuits from the 1980s and 1990s, including the Williams FW07B, FW12, FW14B, FW18, Ferrari F399, F1/87/88C, Lotus 98T, and 100T. Additional circuits include Estoril, Imola, Brands Hatch and Jerez.' FROM games WHERE igdb_id = 5586 ON CONFLICT (game_id, language_code) DO NOTHING;
