INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solarium', 'The year is 1954. One year after mutually assured destruction. And I am trying to find you, through memory and alchemy. Not many people know how the nuclear devastation really happened. But we do. We were part of Solarium.' FROM games WHERE igdb_id = 139307 ON CONFLICT (game_id, language_code) DO NOTHING;
