INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Denpa Men 2: Beyond the Waves', 'The Denpa Men are mysterious little creatures that float around radio waves. They all have their own territory. You can''t see them with the naked eye, but you can use your 3DS to find them and catch them. In this RPG, you can form a team of the Denpa Men you caught and take them on an exciting adventure across the world, in order to save the hero''s family. Many wonders and strong enemies await you on your journey!' FROM games WHERE igdb_id = 63484 ON CONFLICT (game_id, language_code) DO NOTHING;
