INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Habitica', 'Habitica is a game to help you improve real-life habits. It "gamifies" your life by giving you in-game rewards for your real-life tasks. The better you are at accomplishing real-life tasks, the more you progress in the game. If you slip up in life, your character starts backsliding in the game.' FROM games WHERE igdb_id = 395187 ON CONFLICT (game_id, language_code) DO NOTHING;
