INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bread Kittens', 'Take a journey into the world of Catlandia where innocent kittens are being brainwashed by the evil ChowCorp and held from their free will! Save and collect as many kittens as you can by breading them, travel through each region to find unique kittens, and bake delicious bread to wear on your cat to help in battles!' FROM games WHERE igdb_id = 159352 ON CONFLICT (game_id, language_code) DO NOTHING;
