INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Amazing Spider-Man: Ultimate Edition', 'The Amazing Spider-Man: Ultimate Edition is a special version of the 2012 video game The Amazing Spider-Man, released exclusively for the Wii U in 2013. This edition includes all previously released downloadable content (DLC) on-disc, offering additional missions, characters, and suits unavailable in the original game. Some of the notable DLC content includes the "Lizard Rampage Pack," "Oscorp Search and Destroy Pack," "Stan Lee Adventure Pack," and new suits like the Vigilante and Classic Spider-Man suits.' FROM games WHERE igdb_id = 23514 ON CONFLICT (game_id, language_code) DO NOTHING;
