INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Persona 4 Arena Ultimax', 'Persona 4 Arena Ultimax is a fighting video game developed by Arc System Works and Atlus. It is the direct sequel to Persona 4 Arena, which is itself a follow-up to the role-playing game Persona 4. The game was originally released in Japanese arcades on November 28, 2013, and later ported to home consoles. Unlike the previous game, it is not region locked.' FROM games WHERE igdb_id = 11445 ON CONFLICT (game_id, language_code) DO NOTHING;
