INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon''s Lair', 'Dragon''s Lair is a high-definition re-release of the classic 1983 arcade game, featuring fully remastered animation by Don Bluth. Players control Dirk the Daring, a brave knight on a quest to rescue Princess Daphne from the evil dragon Singe, navigating through a series of animated sequences using quick-time events. Originally notable for its use of LaserDisc technology, the game presents hand-drawn animation where players must react to on-screen prompts to survive. The remastered edition enhances the original experience with 720p HD visuals, restored game footage, and bonus content, including interviews with the game''s creators.' FROM games WHERE igdb_id = 126283 ON CONFLICT (game_id, language_code) DO NOTHING;
