INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Mahjong', 'Restore hope to a royal couple and their kingdom in Age of Mahjong, a wonderful challenge with unique goals. Nothing is dearer to the Emperor and Empress than their son. When an unknown disease strikes the young boy, the king calls in healers but they are unable to find a cure. Construction of their new city must progress however, and in this, they might just find the cure.' FROM games WHERE igdb_id = 52376 ON CONFLICT (game_id, language_code) DO NOTHING;
