INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last of Us: Survival Edition', 'The Last of Us: Survival Edition is a special edition of The Last of Us released exclusively in North America for PlayStation 3. It includes the game in a SteelBook case, a mini artbook from Dark Horse featuring concept art and commentary, a variant cover of The Last of Us: American Dreams #1 comic, a Naughty Dog sticker sheet, and a digital content code. The included digital items are the Sights & Sounds Pack (official soundtrack, PS3 dynamic theme, and avatars for Joel and Ellie) and the Survival Pack, which offers multiplayer bonuses such as XP boosts, in-game currency, customizable items, and character skins unlocked after completing the single-player campaign.' FROM games WHERE igdb_id = 102082 ON CONFLICT (game_id, language_code) DO NOTHING;
