INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Highborn', 'This witty, wacky, turn-based strategy game is now available for Steam. In Highborn, you’re treated to a strategy game that offers an intelligent, tactical experience without the frenetic play of a traditional RTS. Move your forces around an overhead map to secure spells and combat support, then dive into combat to deploy those advantages against an unsuspecting enemy. All the fun and fighting is set against an irreverent tale, filled with wacky heroes, witty dialogue and wild assumptions.' FROM games WHERE igdb_id = 15297 ON CONFLICT (game_id, language_code) DO NOTHING;
