INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts Final Mix', 'Originally released only in Japan on December 26, 2002, Kingdom Hearts Final Mix is finally brought to the global scene as an HD Remaster in the collection "Kingdom Hearts HD 1.5 ReMIX". It has several events and a number of gameplay tweaks that are not in previous releases. New scenes, clarifying certain plot points, such as Riku''s journey and foreshadowing of Kingdom Hearts II, were included, but no new dialogue was recorded. A gameplay option allows the player to skip cutscenes. The optional bosses are included, along with a new fight against "Unknown Man."' FROM games WHERE igdb_id = 212758 ON CONFLICT (game_id, language_code) DO NOTHING;
