INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('killer-is-dead', 2940, '2013-08-01', 57, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4wxz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jvvkf7a2k5j6mxoyio8h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killer Is Dead', 'Killer is Dead is an action game that is no sequel to Killer7 or the No More Heroes series by the same developers, but shares elements such as violent action, a main character wielding a katana as the most prominent weapon, assassins as an important theme, and a cel shaded visual style. The game is divided into 12 episodes in locations all over the world and stars Mondo Zap as the main character. He is a contract executioner who works for the he Bryan Execution Firm. The game is set in the future and Monda receives jobs to kill cyborgs and assassins. Before each mission a brief overview of the objective is shown against a world map and in between the fighting there are often animated sequences that further the story. Completing a main mission usually opens up several side missions.' FROM games WHERE igdb_id = 2940 ON CONFLICT (game_id, language_code) DO NOTHING;
