INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Incredible Adventures of Van Helsing', 'Put on your wide-brimmed hat, grab your weapons and embark on an incredible adventure in the gothic-noir world of Borgovia, where mad science threatens the fragile peace between monster and mortal. Be Van Helsing, monster-hunter extraordinaire and save the day with your charming and beautiful companion, Lady Katarina. Explore the savage wilderness in the mountains and the soot-stained brick districts of a grim metropolis twisted by weird science, and don’t forget: you might never know who the real monsters are!' FROM games WHERE igdb_id = 2638 ON CONFLICT (game_id, language_code) DO NOTHING;
