INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('skulls-of-the-shogun-bone-a-fide-edition', 51906, '2013-07-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2212.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar577.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skulls of the Shogun: Bone-A-Fide Edition', 'Washing up on the shores of the afterlife, players meet and join forces with vibrant ghost-samurai warriors, magical animal-monks, and mustachioed samurai generals on the way to capture Skulls of the Shogun. With its roots in classic turn-based strategy gaming, Skulls of the Shogun retains depth and adds a smooth, simple interface that makes it accessible and enjoyable even to players new to the genre. Players immerse themselves in battle with fun and unique game play features amidst lush, eerie environments. Also featuring 4-player local and networked multi-player and an original score inspired by old samurai films and dub, Skulls of the Shogun offers simple-yet-deep, refined and offbeat game-play.' FROM games WHERE igdb_id = 51906 ON CONFLICT (game_id, language_code) DO NOTHING;
