INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Murder In Tehran''s Alleys 1933', 'A series of brutal and frightening killings have gripped the city of Tehran. Tortured before being cut to pieces, the victims are innocent children living downtown, and there seems to be no clear motive behind the murders. With the media fuelling public hysteria, it''s up to detective Afshar to solve the case, with help from a journalist named Sarsolooki, who believes there''s much more to the killings than the random violent acts of a madman.' FROM games WHERE igdb_id = 25269 ON CONFLICT (game_id, language_code) DO NOTHING;
