INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toukiden: The Age of Demons', 'An expansive fantasy world influenced by historical and traditional Japanese elements. This new franchise casts players in the role of the demon-fighting warrior, known as a Slayer. Starting from the Utakata Village headquarters where they will accept quests, players will venture out to battle monstrous and deadly Oni (demons) before they destroy all of humanity. Players can select party members from a supporting cast of characters, or join together with up to three other players through ad-hoc mode.' FROM games WHERE igdb_id = 8658 ON CONFLICT (game_id, language_code) DO NOTHING;
