INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'UnderRail', 'Underrail is an old school turn-based isometric indie role playing game that focuses on exploration and combat. The player takes control of one of the denizens of such a station-state whose life is about to become all that much more interesting and dangerous, as our protagonist is caught midst the conflicting factions of the Underrail as the violently struggle to survive in the harsh underground environment.' FROM games WHERE igdb_id = 16657 ON CONFLICT (game_id, language_code) DO NOTHING;
