INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Rising 3', 'Available exclusively for Xbox One and Windows, Dead Rising 3 marks the return of one of the most popular zombie video game franchises. Set 10 years after the events of Fortune City in Dead Rising 2, players are introduced to Nick Ramos, a young mechanic with a strange tattoo and a mysterious past, who must find a way to escape a city full of zombies before an impending military strike wipes the city of Los Perdidos, California, and everyone in it, off the map. Nick can’t do it alone – he must join up with other survivors to stay alive. They must fight their way out before it’s too late.' FROM games WHERE igdb_id = 3199 ON CONFLICT (game_id, language_code) DO NOTHING;
