INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last of Us: Post-Pandemic Edition', 'The Last of Us: Post-Pandemic Edition is a special edition of The Last of Us released exclusively in North America for PlayStation 3. It includes the game on disc in a SteelBook case, a 12-inch premium statue of Joel and Ellie by Project Triforce, a variant cover of The Last of Us: American Dreams #1 comic, and a sheet of Naughty Dog stickers. The edition also comes with two downloadable content packs: the Sights & Sounds Pack (digital soundtrack, PS3 dynamic theme, and character avatars) and the Survival Pack (multiplayer bonuses, in-game currency, weapon upgrades, and unlockable character skins).' FROM games WHERE igdb_id = 102083 ON CONFLICT (game_id, language_code) DO NOTHING;
