INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Army of Two: The Devil''s Cartel', 'In Army Of Two: The Devil''s Cartel, players find themselves on the deadly streets of Mexico as Alpha and Bravo, two operatives working for Tactical Worldwide Operations (T.W.O.), a PMC outfit that drops them in the middle of a drug war conflict for an assignment full of corruption and deceit. With the ability to unleash the power of ultimate destruction, players will need to work together as their objectives unravel, allegiances begin to blur and they face off against a ruthless opposition.' FROM games WHERE igdb_id = 1832 ON CONFLICT (game_id, language_code) DO NOTHING;
