INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earth Defense Force 2025', 'Earth Defense Force 2025 is the long awaited follow-up in the Earth Defense Force (EDF) series from Japanese developer Sandlot. The insects return from dormancy to end humanity with over-the-top action and massive city-leveling explosions that will entrench the EDF and the citizens of Earth into a state of emergency.' FROM games WHERE igdb_id = 5585 ON CONFLICT (game_id, language_code) DO NOTHING;
