INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shuutai Headless', 'Erina is a girl who appears in a mysterious place that seems to be an old prison. When she explores the place, she encounters the mysterious character known as the Red Witch, she warns her that place is full of evilness and prisoners who seek for revenge. Erina must find the way to escape from that place without being caught by the prisoners.' FROM games WHERE igdb_id = 150575 ON CONFLICT (game_id, language_code) DO NOTHING;
