INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Kart Arcade GP DX', 'Mario Kart Arcade GP DX is a Mario Kart game for arcade systems, developed by Namco Bandai Games in partnership with Nintendo. It is the tenth installment in the Mario Kart franchise and the third title in the Arcade series following Mario Kart Arcade GP 2, which was a follow-up to Mario Kart Arcade GP. The game was released in Japan on July 25, 2013 and in the United States during 2014. Just like the previous two Arcade GP games, it is possible to do multiplayer play by linking up to four cabinets.' FROM games WHERE igdb_id = 19840 ON CONFLICT (game_id, language_code) DO NOTHING;
