INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless Skater', 'Flip, Grab, and Grind your way to the longest runs and highest scores in Endless Skater! Air it out on ramps, across rails and even over the rooftops! Choose from five of the top professionals to ever set foot on a skateboard and jump into endless levels that challenge you to get as far as you can, or score as many points as you can. Discover dozens of tricks and combos - including secret, hidden signature tricks. Go for huge air, long grinds, and big flips! But watch out...you can also take some huge spills!' FROM games WHERE igdb_id = 61755 ON CONFLICT (game_id, language_code) DO NOTHING;
