INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bureau: XCOM Declassified', 'The year is 1962 and the Cold War has the nation gripped by fear. A top-secret government unit called The Bureau begins investigating a series of mysterious attacks by an enemy more powerful than communism. As agent Carter, call the shots, pull the trigger and lead your squad in a gripping third-person tactical shooter set within a covert war to protect humanity from an otherworldly enemy.' FROM games WHERE igdb_id = 244 ON CONFLICT (game_id, language_code) DO NOTHING;
