INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kentucky Route Zero', 'Kentucky Route Zero is a magical realist adventure game about a secret highway in the caves beneath Kentucky, and the mysterious folks who travel it. Gameplay is inspired by point-and-click adventure games (like the classic Monkey Island or King''s Quest series, or more recently Telltale''s Walking Dead series), but focused on characterization, atmosphere and storytelling rather than clever puzzles or challenges of skill.
