INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Am Vegend: Zombiegeddon', 'Captain the Vegendary Heroes, survive the Zombiegeddon and take revenge upon the birds, the pigs, and the zombies! Enjoy this mind-blowing travesty of mobile game hits! - Enemies have joined forces to destroy all plants! They trample down young innocent seedlings, besiege the allotment and steal the seeds! Take charge of Vegendary Heroes special fertilisation squad and box the blighters mugs! To win, you will have to use anything that can shoot – and you''ll find that nearly everything CAN! - The final battle will require total involvement: baste the birds with tomatoes, take advantage of carrot ordnance, chop zombies and sprinkle on the salad to watch your green-as-grass recruits grow into seasoned sergeants.' FROM games WHERE igdb_id = 17426 ON CONFLICT (game_id, language_code) DO NOTHING;
