INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Attack on Titan: Lost in the Cruel World', 'Lost in the Cruel World is a visual novel by Hiroshi Seko. It was first released on September 18th, 2013 in Japan bundled with the third anime Blu-ray. The story was also included in the novel Attack on Titan: Lost Girls which was later adapted into a manga of the same name.' FROM games WHERE igdb_id = 200586 ON CONFLICT (game_id, language_code) DO NOTHING;
