INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: The Lecarde Chronicles', 'Castlevania: The Lecarde Chronicles is a fan-game produced by independent free-game producer Migami Games in the year 2013. This game is more or less like classic Castlevania games as players collect sub-weapons, hearts, power-ups and make progress in separated stages. The game has its beautiful original sprites, graphics and remixed music from various Castlevania titles, presented in a familiar yet fresh way.' FROM games WHERE igdb_id = 131704 ON CONFLICT (game_id, language_code) DO NOTHING;
