INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Princess of Arcadias', 'The kingdom of Schwert was once peaceful and beautiful. But now it''s been overrun by monsters, and as the Battle Princess Plume, it''s up to you to set things right in this colorful, high- speed action RPG! Recruit a group of warriors and engage in skirmishes against the enemy before taking on huge and powerful bosses in epic siege battles!' FROM games WHERE igdb_id = 9068 ON CONFLICT (game_id, language_code) DO NOTHING;
