INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Badland', 'Badland is an award-winning atmospheric side-scrolling action-adventure game that takes platforming to the next level with innovative use of physics in level design. It immerses players in an audiovisual gaming experience through a lush forest full of various inhabitants, trees and flowers. Although the forest appears to be right out of a beautiful fairy tale, there’s something terribly wrong. The player controls one of the forest dwellers to find out what’s going on, and discovers an astonishing number of imaginative traps and obstacles on the way.' FROM games WHERE igdb_id = 8901 ON CONFLICT (game_id, language_code) DO NOTHING;
