INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Muramasa Rebirth: Blessing of Amitabha Collector''s Edition', 'Aksys Games is pleased to announce the Muramasa Rebirth Blessing of Amitabha Collector’s Edition! This special limited run collector’s edition will set your PlayStationVita handheld entertainment system apart from everyone else’s! Fully immerse yourself in the visually stunning world of Muramasa Rebirth, a world where myth and legend collide in this action-packed RPG designed specifically for the PlayStationVita system!
