INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Live 14', 'Powered by EA SPORTS IGNITE, NBA LIVE 14 delivers the ultimate on court control combining the art of basketball with the science of next generation technology. bounceTek, fueled by next-gen visual fidelity and up to 8x the processing power, unlocks a revolutionary new, physics-based dribbling system. Players perform more like their real-life counterparts than ever before, informed by 70+ stats and tendencies, updated not monthly, weekly or daily, but within 1-hr of every NBA game. With fresh content and challenges on a daily basis, NBA LIVE 14 delivers the pulse of the NBA...24/7/365.' FROM games WHERE igdb_id = 5330 ON CONFLICT (game_id, language_code) DO NOTHING;
