INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slender: The Arrival', 'Slender: The Arrival is the official continuation of the series from the original game creator Mark Hadley, teamed up with the writers behind the Marble Hornets series and the development team at Blue Isle Studios. The Arrival features a brand new storyline, improved visuals and most importantly, survival horror at its best. Slender: The Arrival now officially supports the Oculus Rift – a next generation virtual headset designed for super immersive gaming! The Rift intensifies the fear-factor, and gives players a brand new, immersive horror experience.' FROM games WHERE igdb_id = 2049 ON CONFLICT (game_id, language_code) DO NOTHING;
