INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadows: Price For Our Sins', 'Are you ready to party? A chilling night of reckoning is unleashed upon guests bold enough to party on Halloween at an abandoned farm house. As children, you and your friend, Samantha, would play at an old farm during your summer vacations. Years have passed, and Samantha has invited you to join her and a group of fellow students back at the farm for a Halloween party. Little does anyone know - but a demonic force will be crashing the event.' FROM games WHERE igdb_id = 16793 ON CONFLICT (game_id, language_code) DO NOTHING;
