INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TX Poker: Texas Holdem Online', 'TX Poker – Texas Holdem Online is a free-to-play mobile poker game developed by Murka Games. It offers authentic Texas Hold’em gameplay with various modes, including Dash Poker, Sit-N-Go, and Golden Tournaments. Players can enjoy multiplayer poker matches, participate in daily challenges, and win chips in jackpots and tournaments. Suitable for both beginners and experienced players, the game supports multiple languages and features in-app purchases for an enhanced experience.' FROM games WHERE igdb_id = 359912 ON CONFLICT (game_id, language_code) DO NOTHING;
