INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek Trexels', 'Star Trek Trexels is a video game for iOS and Android devices in which you are an admiral in control of a starship exploring a newly-discovered region of space, named the Trexelian Expanse, for the USS Valiant, whose current status is unknown. The game is a micro-manager in which you build rooms on the ship, train crew, and control them in their day-to-day functions.' FROM games WHERE igdb_id = 123152 ON CONFLICT (game_id, language_code) DO NOTHING;
