INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Maiden''s Serenade', 'The Mermaid Festival is an annual festival that takes place in the coastal town of Suminoe and on the night of the festival, Takumi meets a girl with a beautiful singing voice. From this chance encounter, Takumi''s daily life slowly begins to change. The 7th project by developer, feng.' FROM games WHERE igdb_id = 302680 ON CONFLICT (game_id, language_code) DO NOTHING;
