INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('secrets-of-the-dark-mystery-of-the-ancestral-estate', 63442, '2013-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/toosi1c4ker2ixsihniq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctmhe.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secrets of the Dark: Mystery of the Ancestral Estate', '"Mystery of the Ancestral Estate" is the third game in the Secrets of the Dark series. Like the first two it is a hidden object game. Screens have a list of objects that need to be found. Each object found is struck off the list. Items gathered during your journey are stored in an inventory. These items are then used to solve puzzles in the hope of obtaining a piece of the house''s lamp. As before light and dark needs to be manipulated in order to discover items and puzzles that need completing. Puzzles need to be solved and vary in difficulty. Hints can be used to find hidden objects, to provide assistance as to what to do next or to skip puzzles.' FROM games WHERE igdb_id = 63442 ON CONFLICT (game_id, language_code) DO NOTHING;
