INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tank Operations: European Campaign', 'Tank Operations: European Campaign is a turn-based, tactical wargame featuring a dozen nail-biting historical scenarios set on the diverse battlefields of World War II. With more than 50 faithfully-rendered, authentic military combat units, along with sabotage options and the need to manage your supply chain, the game will keep armchair generals occupied for hours in realistic combat scenarios.' FROM games WHERE igdb_id = 16740 ON CONFLICT (game_id, language_code) DO NOTHING;
