INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'QuizUp', 'QuizUp is a mobile game developed by Iceland-based Plain Vanilla Games. The game is a mobile trivia app similar to the game Trivial Pursuit. QuizUp is a single-player game in which one user competes against another during seven rounds of timed multiple-choice questions of various topics. There are over 680 total categories of topics available to users to choose from and all the questions are voluntarily submitted by content contributors. Most categories are available in different languages.' FROM games WHERE igdb_id = 9487 ON CONFLICT (game_id, language_code) DO NOTHING;
