INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Injustice: Gods Among Us', 'What if our greatest heroes became our greatest threat? Injustice: Gods Among Us introduces a bold new franchise to the fighting game genre from NetherRealm Studios, creators of the definitive fighting game Mortal Kombat. Featuring DC Comics icons such Batman, Cyborg, The Flash, Harley Quinn, Nightwing, Solomon Grundy, Superman and Wonder Woman, the latest title from the award-winning studio presents a deep original story. Heroes and villains will engage in epic battles on a massive scale in a world where the line between good and evil has been blurred.' FROM games WHERE igdb_id = 1918 ON CONFLICT (game_id, language_code) DO NOTHING;
