INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avakin Life', 'The amazing virtual world where you can become the person you always wanted to be! Browse thousands of clothing items from amazing fashionable brands to create your perfect look. Explore incredible locations and chat with millions of players from all around the world! Hang out in your customisable apartment where you can relax with friends, or simply enjoy the company of your very own virtual pet. Join up now, and invite your friends to explore the ever-growing virtual 3D world of AVAKIN LIFE!' FROM games WHERE igdb_id = 86966 ON CONFLICT (game_id, language_code) DO NOTHING;
