INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cities in Motion 2', 'Cities in Motion 2 (CIM2) is the sequel to the popular mass transit simulation game Cities in Motion. Build, manage and lead your transportation network to provide cities with their ever changing needs. Cities in Motion 2 introduces new features including multiplayer game modes, day and night cycles, timetables and dynamic cities.' FROM games WHERE igdb_id = 2931 ON CONFLICT (game_id, language_code) DO NOTHING;
