INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sorcery Saga: Curse of the Great Curry God', 'Play as Pupuru, a young, ambitious girl on a quest to obtain ingredients for the legendary curry to save her friend’s restaurant. With the help of the moody creature Kuu and the noncommittal Puni, she’ll have to defeat the host of weird, sometimes appetizing creatures that stand in her way! But beware, once you enter a dungeon, Pupuru will need all her skills to fight fore if she falls, her levels and items obtained will disappear! Get ready for a truly delectable storyline with a side of awesome, challenging gameplay!' FROM games WHERE igdb_id = 19915 ON CONFLICT (game_id, language_code) DO NOTHING;
