INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hyperdimension-neptunia-producing-perfection', 9867, '2013-06-20', 38, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mkd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zfb8ih8hryf2fqzhdkau.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyperdimension Neptunia: Producing Perfection', 'You take on the role of the main character, who happens to fall into Gamindustri and is immediately hired by one of the four CPUs-Neptune, Noire, Blanc, and Vert-to be their producer and manage their idol careers. Get your training wheels on, ladies, because a new producer is in town and the fate of Gamindustri hangs in the balance! Will you be able to properly raise these CPUs into idols, or will their citizens be stolen away from them by the popular idol group MOB-48!? Teach these girls to sing, dance, and properly promote themselves to the general populace thanks in part to your expertise in training video game idols back on Earth. As the girls'' popularity rises, they will be able to join one another in singing duets, or maybe even come together for a full ensemble!' FROM games WHERE igdb_id = 9867 ON CONFLICT (game_id, language_code) DO NOTHING;
