INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gone Home', 'A first-person exploratory game taking place in 1995 in which Katie, a university student back from Europe, arrives at her family''s newly inherited mansion only to find nobody there, with a note from her younger sister Sam suggesting that she''s left home. Katie must explore the mansion to put together the stories of where her parents have gone and why Sam has decided to leave.' FROM games WHERE igdb_id = 1906 ON CONFLICT (game_id, language_code) DO NOTHING;
