INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love Live! School Idol Festival', 'Love Live! School idol festival is a free-to-play rhythm game released for iOS and Android, based on the Love Live! franchise. The game features two modes (Story and Live) and all nine members of the idol group μ''s. The school idol group Aqours was later added to the game as a major update on July 5, 2016 with its accompanying songs, stories, cards and events. The players are free to switch between μ''s and Aqours mode in the game.' FROM games WHERE igdb_id = 36660 ON CONFLICT (game_id, language_code) DO NOTHING;
