INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'March of the Eagles', 'The strategy wargame March of the Eagles is dedicated to the era 1805-1820 focused on the dramatic conflicts of Europe. March of the Eagles explores one of the defining periods in European history in an experience crafted by Paradox Development Studio, the masters of Grand Strategy and makers of Hearts of Iron and Europa Universalis. The Napoleonic War is brought to life in this war-focused strategy game.' FROM games WHERE igdb_id = 2936 ON CONFLICT (game_id, language_code) DO NOTHING;
