INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Criminal Girls: Invite Only', 'Criminal Girls: Invite Only a Japanese role-playing game and the enhanced version of the original Criminal Girls game. The game follows a group of girls in Hell who have to climb a tower to be reincarnated. The battle system is unique since you give the characters, each representing a different vice, orders in battle and sometimes they won’t listen to you because they haven’t been trained.' FROM games WHERE igdb_id = 11746 ON CONFLICT (game_id, language_code) DO NOTHING;
