INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conception II: Children of the Seven Stars', 'Conception II: Children of the Seven Stars is a Japanese role-playing video game and a follow-up to Conception: Ore no Kodomo o Undekure!. The player control a student at a high school that doubles as a training facility for demon hunters. The protagonist possesses an extremely high amount of ether in his body, which allows him to conceive Star Children to fight demons by "classmating" with his other classmates. During battle, fighters can be strategically placed around the enemies, allowing players to either safely target weak points or charge head on for bigger rewards.' FROM games WHERE igdb_id = 4701 ON CONFLICT (game_id, language_code) DO NOTHING;
