INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alicemare', 'Alicemare is a somehow familiar yet totally unique adventure game with strong horror leanings, created by △○□× (Miwashiba) using the Wolf RPG Editor. The game follows an amnesiac young boy named Allen who was placed under the care of a man called Teacher who looks after four other children.' FROM games WHERE igdb_id = 26138 ON CONFLICT (game_id, language_code) DO NOTHING;
