INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paint it Back', 'The art has disappeared from the gallery! Can you paint it back? Recreate lost works of pixel art using logic as your paintbrush. Solve paintings like "Enormous Ant Goes Sightseeing" and "Satan is My Neighbor" to win achievements and restore the gallery to its former glory.' FROM games WHERE igdb_id = 16311 ON CONFLICT (game_id, language_code) DO NOTHING;
