INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkfall Unholy Wars', 'Darkfall Unholy Wars is an innovative, Real-Time, fast-paced, PvP, Sandbox MMORPG. Players are called to form clans and battle for dominance across the seamless, zoneless, uninstanced open fantasy world of Agon. Recruit and train new warriors, conquer fortresses and clan cities, engage in epic land and naval battles with thousands of concurrent players to build and defend powerful empires.' FROM games WHERE igdb_id = 8185 ON CONFLICT (game_id, language_code) DO NOTHING;
