INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Matter', 'Dark Matter is a 2.5D side-scrolling survival horror game, set in a derelict spaceship besieged by a sinister alien presence, and infested with deadly parasites. As the Ensign, you must explore fetid hallways and abandoned facilities, scavenging for parts and blueprints, expanding your arsenal to up to four deadly weapons and freely customize each to fit your combat style against intelligent, reactive enemies. Dark Matter delivers a hard-hitting take on the survival horror genre in deep space, with a heavy emphasis on tactical combat and exploration.' FROM games WHERE igdb_id = 16668 ON CONFLICT (game_id, language_code) DO NOTHING;
