INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fairy Fencer F', 'Fairy Fencer F is a fantasy role-playing game under Compile Heart''s Galapagos RPG brand for the PlayStation 3. It features Yoshitaka Amano as a concept artist, Nobuo Uematsu as a composer, Tsunako as a character designer, Toshiki Inoue as a screen writer and the "Neptunia Team" as some of the development team. The game uses an evolved version of Hyperdimension Neptunia ''​s battle system. A Windows PC port for Steam is announced for an unspecified release date in 2015.' FROM games WHERE igdb_id = 9893 ON CONFLICT (game_id, language_code) DO NOTHING;
