INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dmbx-2-dot-5-mountain-bike-and-bmx', 174338, '2013-11-21', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DMBX 2.5: Mountain Bike and BMX', 'DMBX gets to the next round: featuring Mountain Bike and BMX action, brand new Downhill, Slopestyle, Vert Ramp, Dirt-Pipe and Big Air levels, ghost and battle races, new bikes and individual characters from head-to-toe, replay options with video and picture export, completely new animations and physics, easy trick-steering and much more! Did you ever want to drop into a vert ramp with your BMX? Or throw yourself over a big air? Maybe you are just about ready to conquer the steepest downhill ever? DMBX is finally here and it will be the perfect fit! Choose and edit your individual character, find your bike or BMX to go along and let’s do it! Master the local challenges to unlock new tricks, new levels, bikes as well as characters and proof your skills against the very best players on the globe in a battle race. If you are free from giddiness and ready for a new dimension - check out the brand new viewing angle option which can guarantee for an exclusive game experience that is one-of-a-kind! All levels - including the vert ramp and big air - can be played in this “First Person View” mode. In addition you can also change into the First Person View mode during the Replay Mode! So what are you waiting for? Gear up and let`s go!!' FROM games WHERE igdb_id = 174338 ON CONFLICT (game_id, language_code) DO NOTHING;
