INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chainsaw Warrior', 'Chainsaw Warrior is a classic nail-biting game for one strong-nerved player, based off the single-player board game of the same name. The player has sixty minutes to navigate a labyrinth composed of an abandoned urban slum in New York, represented by two decks of cards, locate the entity Darkness attempting to destroy the city and kill it.' FROM games WHERE igdb_id = 16672 ON CONFLICT (game_id, language_code) DO NOTHING;
