INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aqua Kitty: Milk Mine Defender', 'Due to a sudden shortage of milk, cats around the world are forced to seek out new sources to get their fix. You and your team of milk mining kittens have overcome a fear of water to drill down under the ocean seabed and begin extracting vast reserves of what seems to be naturally forming full-fat milk. Get ready for fast paced submarine action, defending the kittens from disruptive mechanical sea creatures. The milk must flow!' FROM games WHERE igdb_id = 8642 ON CONFLICT (game_id, language_code) DO NOTHING;
