INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('magic-2014-duels-of-the-planeswalkers', 2188, '2013-06-26', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobpva.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hqruy8dmreixqajmqp9k.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic 2014: Duels of the Planeswalkers', 'Magic 2014: Duels of the Planeswalkers is a digital collectible card game that introduces players to the Magic: The Gathering universe. Players assume the role of a Planeswalker, casting spells and summoning creatures across various planes of existence. The game features a campaign where players face Chandra Nalaar and uncover a larger mystery involving her manipulation. It includes a comprehensive tutorial for newcomers, deck-building mechanics through virtual booster packs, and both single-player and multiplayer modes. The game offers 10 unique decks with unlockable cards, multiple campaigns, special encounters, and puzzle-like challenges to complete.' FROM games WHERE igdb_id = 2188 ON CONFLICT (game_id, language_code) DO NOTHING;
