INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scribblenauts Unmasked: A DC Comics Adventure', 'Scribblenauts Unmasked: A DC Comics Adventure is a puzzle video game developed by 5th Cell and published by Warner Bros. Interactive Entertainment. It is the fifth game in the Scribblenauts series of games and the first based on a licensed property. The game combines the series'' traditional gameplay of bringing up words and objects to solve puzzles with characters and settings from the DC Comics universe (DC Universe).' FROM games WHERE igdb_id = 5033 ON CONFLICT (game_id, language_code) DO NOTHING;
