INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evertales', 'Once upon time, there was a tale of mighty heroes, protectors of the realm, and the saviors of many damsels in distress. This…is not that tale. This is a tale of unlikely Heroes. Embark on journeys of not-so-epic proportions with Sir Jorgin, the noble knight past his prime; Arwick, the ladies man and elf rogue; and Taragon, wise, old, and somewhat senile wizard. Welcome….to Evertales.' FROM games WHERE igdb_id = 23927 ON CONFLICT (game_id, language_code) DO NOTHING;
