INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Football Playbook: Tactical Puzzles', 'The Football Playbook is a collection of tactical puzzles. In each puzzle you are presented with a snapshot of a football match. To successfully complete the puzzle you must score a goal. Use a combination of timing, movement and key passes to get your players into a scoring position.' FROM games WHERE igdb_id = 197247 ON CONFLICT (game_id, language_code) DO NOTHING;
