INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splatter - Just Harder Times', 'You\''re standing alone amongst the inhabitants of a modern city which suddenly took a turn for the apocalypse. Play an intriguing story line, upgrade your weapons, fight bosses, drive vehicles, meet other characters, and use light to survive. Humanity isn\''t exactly worth saving, but you might end up doing it anyways.' FROM games WHERE igdb_id = 51665 ON CONFLICT (game_id, language_code) DO NOTHING;
