INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Useful Dead', 'The Useful Dead is a puzzle game where you have to die to progress. You control a horde of critically-stupid critters who can use each other’s dead bodies as stepping stones, to hold down buttons, prop open doors, etc. It features about 50 levels and is meant to be a simple, fun time.' FROM games WHERE igdb_id = 62830 ON CONFLICT (game_id, language_code) DO NOTHING;
