INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai vs. Zombies Defense 2', 'The Samurai is back... and he’s brought friends! Play as the heroic Samurai, the deadly Kunoichi Assassin, and the stalwart Armored Ronin to defend your village against even nastier hordes of brutal zombies and demons! Recruit allies, build defenses, and recover sacred Artifacts to stop them!' FROM games WHERE igdb_id = 127047 ON CONFLICT (game_id, language_code) DO NOTHING;
