INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxy on Fire: Alliances', 'Wormholes open. Conquerors appear. Planets fall. The Shroud Nebula is about to be seized and raided. And only YOU can stop it. Team up with longtime allies and old enemies alike to face the ruthless invaders, steal their rare treasures and build their superior carriers! Save the galaxy from the tyranny of the Voids!' FROM games WHERE igdb_id = 261530 ON CONFLICT (game_id, language_code) DO NOTHING;
