INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farmington Tales 2: Winter Crop', 'Explore snowy Dahlia Farms in a unique combination of hidden object game and farming simulation. Floyd and Dahlia have retired and Kaylee has taken over, but winter is setting in and she''s a bit out of her element. Search your property for items to sell in the market, plant and harvest crops, and buy new upgrades to fix up the farm.' FROM games WHERE igdb_id = 294225 ON CONFLICT (game_id, language_code) DO NOTHING;
