INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disney-infinity', 2926, '2013-08-18', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1psn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lpmgubjxcgagbn1mkjol.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Infinity', 'DISNEY INFINITY unlocks the freedom to play with some of your favorite Disney and Disney/Pixar worlds like never before! You can experience adventures in the worlds of Pirates of the Caribbean, The Incredibles and Monsters University - take on the role of Sulley, the naturally gifted ‘scarer’; become Captain Jack Sparrow, the sword-wielding pirate; or transform yourself into Mr. Incredible, one of the world''s greatest crime-fighters. Battle enemies, solve puzzles, overcome obstacles and complete a variety of other unique quests. Or create your own world! Unlock virtual toys, characters, buildings, weapons, gadgets and more – and bring them into the Disney Infinity ‘Toy Box’ where you can mix them all up to create your own game. In the Disney Infinity Toy Box, there are no rules and you can create any adventure you want. Share your creations with your friends with up to 4-player co-op play. The more you play, the more you unlock so the story never ends. It’s up to you and your imagination – infinite possibilities, infinite ways to inspire your imagination!' FROM games WHERE igdb_id = 2926 ON CONFLICT (game_id, language_code) DO NOTHING;
