INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shelter SCG', 'Zombie card dueling in a graphic novel style - tasty! Playing like a hybrid of a collectible card game and the castle defense genre, Shelter will provide you with hours of challenging play. Defend yourself from the zombie onslaught as you fight to be reunited with the woman you love. You define your strategy, but be warned... No single strategy will win.' FROM games WHERE igdb_id = 175056 ON CONFLICT (game_id, language_code) DO NOTHING;
