INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turbo: Super Stunt Squad', 'Turbo: Super Stunt Squad is a high-velocity action game featuring the super-charged crew of characters from the upcoming film. Each playable character has their own signature street style and tricked-out skills which will come in handy when showing-off and earning respect with jumps, drifts, grinds, flips and other super-cool stunt moves. Expert skills will also prove useful to earn power-ups, customize your character, win competitive challenges and discover shortcuts in the dynamic larger-than-life environments of Turbo''s world.' FROM games WHERE igdb_id = 11053 ON CONFLICT (game_id, language_code) DO NOTHING;
