INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dead-heat-riders', 288175, '2013-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7t0q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqqel.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Heat Riders', 'Based on Bandai Namco’s popular Dead Heat Street Racing arcade game, Dead Heat Riders takes that same exciting, neck-and-neck racing premise and applies it to motorcycle racing. Hop on your bike to race through 4 incredibly detailed cities, which were personally surveyed by the development team. Just like the Dead Heat street racing game, zoom through the streets of New York, Chicago, London and San Francisco but now on different courses through each city. Select from 5 different superbikes as you ride on a recreated motorcycle swivel seat. Another great feature is found with Namco’s patented software technology that analyses and stores registered players driving styles, later mimicking registered players as “ghost drivers”. This allows current players to race against previous drives, even when they are not around. This title also features a completely revamped soundtrack, designed to match the white knuckle intensity of each race. Enjoy more social racing with the Integrated Camera! This takes a picture of the players and uses that photo to identify your car and other players you are racing against in real-time during the race.' FROM games WHERE igdb_id = 288175 ON CONFLICT (game_id, language_code) DO NOTHING;
