INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sewage', 'Sewage is a Chinese Yume Nikki fangame. You play a girl named Xuán Wō Zǐ. Like other fangames, the objective of the game is to explore the dream world and collect Items. Goods don''t change the protagonist''s form or do anything at all. Rather, they seem to be memories from the protagonist''s past.' FROM games WHERE igdb_id = 202329 ON CONFLICT (game_id, language_code) DO NOTHING;
