INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Olav & the Lute', 'Is a mystical adventure game. Dive into the post-apocalyptic fantasy world, solve puzzles, discover melodies, change the game-world with your mystical lute and .. fix it? Inspired by the old LOOM, Olav & the Lutemakes use of an extraordinary gameplay mechanic. Discover the melodies of this magical world and use them to change other objects. It''s not like something bad could happen, is it? Will you be able to figure out your mission, and let alone fulfill it?' FROM games WHERE igdb_id = 131996 ON CONFLICT (game_id, language_code) DO NOTHING;
