INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eternity Warriors', 'After 20 years of peace in Northern Udar, a powerful new Demon threat has emerged under the command of the evil Demon King Kilic. The Demons have overrun and transformed the once vibrant land into a cesspool of danger and evil. Only the courageous Eternity Warriors can defeat this rising threat to the world of Humans and Elves!' FROM games WHERE igdb_id = 38502 ON CONFLICT (game_id, language_code) DO NOTHING;
