INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Namco High', 'From Homestuck creator Andrew Hussie and universally-acclaimed video game developer Namco Bandai Games comes an all new gaming experience: Namco High! As a cousin to the Prince from Katamari Damacy, you will meet total strangers with whom you have nothing in common, but before the school year is over you''ll break rules, bare your soul, and touch each other in ways you never dreamed.' FROM games WHERE igdb_id = 62502 ON CONFLICT (game_id, language_code) DO NOTHING;
