INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pipe Ball', 'This is a highly addictive puzzle game where you must route the ball to the finish using pipes and speed boosters. With 45 and 90 degree pipes, steer the ball, bounce off walls, retrieve keys to unlock walls, and overcome the friction associated with turning, bouncing and rolling with 2-way and 4-way speed booster pipes. Get maps, create maps, and compete for the best solution to all maps. Maps are stored on a central server and are shared among users once solved.' FROM games WHERE igdb_id = 197732 ON CONFLICT (game_id, language_code) DO NOTHING;
