INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Undead Tower Crusade', 'A plague has swept the town, and zombies have infected the Middle Ages heading for the castle. Join the crusade against the Undead in this tower survival game. There are 15 High Quality 3D levels and 235 waves of the Undead. This is a Tower survival game with zombies based in the middle ages. The game has gore, and a graphics settings menu, for you to change graphics to high or low based on what phone you have. In the future we will be releasing updates and changes.' FROM games WHERE igdb_id = 200246 ON CONFLICT (game_id, language_code) DO NOTHING;
