INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('empire-the-deck-building-strategy-game', 89447, '2013-10-05', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Empire: The Deck Building Strategy Game', 'The barbarous tribes who fought amongst themselves for so many aeons are at last able to come together to found a wondrous civilization. Is yours the first of its kind in this world, or one of many? No man knows, but what all men know is that their Empire must not only survive, but flourish! The world is full of terrible horrors, however, and they will wear away at your Empire from all sides. Natural resources have become more scarce. And perhaps worst of all, your powerful Empire has grown heavy and full of internal strife with its age. How long can you stand the pressures of survival before your Empire finally comes crumbling back down into the desolated earth from which it grew? Empire: The Deck Building Strategy Game introduces the world''s first "Deck-Building 4X Strategy Game". Empire is a quick, easy-to-learn yet difficult to master strategy/tactics game.' FROM games WHERE igdb_id = 89447 ON CONFLICT (game_id, language_code) DO NOTHING;
