INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Ahead', 'Dead Ahead is an endless side-scrolling game. Gameplay requires driving a vehicle down a never-ending road while avoiding obstacles in front and zombies from behind. Leap off ramps to avoid debris, use your weapon to shoot enemies, and survive to achieve high scores. Players can use coins to purchase better rides and guns, upgrade existing ones, or customize their appearance.' FROM games WHERE igdb_id = 196414 ON CONFLICT (game_id, language_code) DO NOTHING;
