INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Rocks', 'Space Rocks is an impressive blending of the classic arcade games Asteroids and Asteroids Deluxe, crafted for the Atari 2600 by Darrell Spice, Jr. If you''re a fan of either arcade cabinet (or both!), you''ll love Space Rocks! While Atari''s version of Asteroids for the 2600 was passable at the time of its release, Space Rocks blasts far ahead of this early effort. Taking full advantage of the DPC+ mode in our Melody Board, Space Rocks pushes the Atari 2600 to its limits and offers a wide variety of gameplay options to keep you playing for years to come. The graphics, animations, and sound effects are well above what is typically experienced on the 2600.' FROM games WHERE igdb_id = 268810 ON CONFLICT (game_id, language_code) DO NOTHING;
