INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No Breaks Valet', 'In No Brakes Valet cars need to be parked in a parking lot presented as a single-screen environment. A car always enter the location at full speed and then only gradually slows down. The player can only steer and needs to time correctly, trying not to bump into edges or other vehicles that were previously parked properly. There are many types of vehicles and also specific parking spots for VIPs and handicapped people.' FROM games WHERE igdb_id = 268949 ON CONFLICT (game_id, language_code) DO NOTHING;
