INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ragnarok: War of Gods', 'Start your journey in Midgard as either a fledgling Swordsman, an apprentice Mage, or a rookie Acolyte as you explore a fantasy world with thousands of other players. Level up your character and upgrade your skills through quests or by defeating monsters ranging from the cute to the menacing using the wide variety of skills at your disposal. Test your might and compete with other players in the PvP arena. Group up with other players to finish quests, gain levels, defeat powerful bosses and complete difficult dungeons.' FROM games WHERE igdb_id = 323174 ON CONFLICT (game_id, language_code) DO NOTHING;
