INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Epigenesis', 'Epigenesis is an online multiplayer sports/FPS game in which two sides are locked in a never-ending fight for world domination by playing ball. In this non-lethal ballgame of the future, players leap across platforms suspended high up in the air trying to get a ball located in the middle of the arena and score goals against their opponents. Each player carries a gravity cannon capable of pushing enemies (and friends) down from the heights of the arena.' FROM games WHERE igdb_id = 16576 ON CONFLICT (game_id, language_code) DO NOTHING;
