INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Texas Hold''em: Daily Poke it!', 'Texas hold ''em is a variation of the standard card game of poker. The game consists of two cards being dealt face down to each player and then five community cards being placed face-up by the dealer - a series of three then two additional single cards, with players having the option to check, bet, raise or fold after each deal.' FROM games WHERE igdb_id = 87154 ON CONFLICT (game_id, language_code) DO NOTHING;
