INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rise of Venice: Beyond the Sea', 'Beyond the Sea is the comprehensive expansion for the acclaimed Renaissance economic simulator Rise of Venice. Beyond the Sea provides players with a whole new challenge by expanding the game world with 13 all new cities to explore and trade with, as well as all new residence missions and challenging new Doge tasks which will see your family playing a more important role. Beyond the Sea also allows players to command a completely new class of ship; the NAO, the famous ship class in which Christopher Columbus discovered America in 1492.' FROM games WHERE igdb_id = 10775 ON CONFLICT (game_id, language_code) DO NOTHING;
