INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: Rivals', 'Warp into the future of card battle games.A highly addictive, strategic, and FREE collectible card game featuring the characters and ships from Star Trek and Star Trek Into Darkness.TOP FEATURES * Easy to learn, difficult to master gameplay * Over 100 cards based on characters, aliens, and starships * Challenge friends or random rivals in turn-based card battles * Earn Federation Credits to buy packs of new cards * Collect XP to increase your level and earn gold-pressed Latinum rewards * Upgrade cards to stronger "Elite" versions Do you have what it takes to become the best in the galaxy?' FROM games WHERE igdb_id = 24551 ON CONFLICT (game_id, language_code) DO NOTHING;
