INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Day One: Garry''s Incident', 'Day One: Garry''s Incident is a PC survival game developed and published by Wild Games Studio in Mascouche, Québec, Canada and released on 25 September 2013. The game received primarily negative reviews from critics. While Garry is transporting cargo for a research facility in Yellowstone National Park, Yellowstone Caldera erupts, causing him to lose control of the plane. An artifact in the cargo causes him to be transported to the Amazon Rainforest, where he discovers an ancient civilization and struggles to survive.' FROM games WHERE igdb_id = 3046 ON CONFLICT (game_id, language_code) DO NOTHING;
