INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('camp-keepalive', 22140, '2013-08-23', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/flo9foi9de5qej2mqqdx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3hu7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
