INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Line GoGo! TwinBee', 'LINE GoGo! TwinBee was a free-to-play infinite vertical scrolling shoot ''em up game developed by Dracolle Studio for iPhone OS and Android smartphones. It was released on May 20, 2013, exclusively in Japan, and it was online only. It is the sixteenth overall TwinBee game and the first shoot ''em up in the series released in 18 years.' FROM games WHERE igdb_id = 282827 ON CONFLICT (game_id, language_code) DO NOTHING;
