INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Surface: The Soaring City', 'Search for your brother, Jeremy, in a beautiful world where the sky is as wide as your imagination in the Hidden Object Puzzle Adventure game, Surface: The Soaring City! Jeremy was a great inventor who discovered a magnificent land soaring in the sky. He created wings for the people, making them free. The new citizens were happy...until one day Jeremy was kidnapped and blamed for conducting inhumane experiments. It''s up to you to save your brother from imprisonment and redeem his good name.' FROM games WHERE igdb_id = 139749 ON CONFLICT (game_id, language_code) DO NOTHING;
