INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magipon!', '"Magipon!" is a puzzle game where the player scores by combining five Magi blocks of the same color. Blocks will not automatically clear once five blocks have been linked. Instead chained blocks can be clear by setting a magic circle on the final block of the chain. Once this final block links with the chain, all the blocks will disappear and be added to your score.' FROM games WHERE igdb_id = 82562 ON CONFLICT (game_id, language_code) DO NOTHING;
