INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Serious Sam Collection', 'Prepare to unleash your inner beast as you go after an army of wicked extraterrestrials. Follow the notorious hero, Sam ''''Serious'' Stone, in his quest to destroy the alien overlord, Mental, in The Serious Sam Collection - the most action-packed compendium of Serious Sam games. Featuring four of the best Serious Sam games ever made, The Serious Sam Collection has been updated with enhanced visuals, lush landscapes, improved textures and character models in HD.' FROM games WHERE igdb_id = 23414 ON CONFLICT (game_id, language_code) DO NOTHING;
