INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hit The Beat', 'Hit The Beat is a drum-style rhythm game that features bright & colorful graphics with a premise that is easy to approach, Unlike other drumming games, the player is not presented with drum-pads – instead there is a multi-color lit dome with a cartoon enemy drawn on it. Hit any part of the dome to coincide with the approaching notes and your character on screen will slash them away. Also instead of standard drumsticks, either of the players uses a set of sponge sticks to dish out the beats. Complete the song for the boss battle at the end of the level!' FROM games WHERE igdb_id = 305164 ON CONFLICT (game_id, language_code) DO NOTHING;
