INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ruki no Zetsubo', 'Ruki Kashima, a 8 years old boy, is home alone when, due to a storm, his house is affected by a blackout. Ruki panics, but not only because he''s afraid of the dark... but also because of that doll that his father keeps and that Ruki believes is cursed.' FROM games WHERE igdb_id = 151798 ON CONFLICT (game_id, language_code) DO NOTHING;
