INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swindler', 'Swindler is a fast-paced, arcade-style adventure game, made with Lucid, a two-dimensional Android exclusive, OpenGL game engine. As the dusk is setting in the Land of Aventyr, you glide through a sea of clouds, steering higher and higher into the High Skies. As captain of your crew, you mercilessly kidnap peasants and princesses to sell them for slave labor, a hefty bounty, or as a food ingredient, amassing ludicrous amounts of loot.' FROM games WHERE igdb_id = 51170 ON CONFLICT (game_id, language_code) DO NOTHING;
